INSERT INTO _migration_506_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_bghl_family_s2_001', 'topic_bece_ghlang_family', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'In Twi, “agya” refers to which family member?', 'multiple_choice', NULL, '["A. Father","B. Mother","C. Uncle","D. Grandfather"]', 'A', 'Agya means father. Mother is ɛna, a (maternal) uncle is wɔfa and a grandfather is nanabarima or nana, so the distractors are different relatives. Therefore the correct answer is A: Father.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_family_s2_002', 'topic_bece_ghlang_family', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'What does the Twi word “ɛna” mean?', 'multiple_choice', NULL, '["A. Sister","B. Mother","C. Grandmother","D. Aunt"]', 'B', 'Ɛna means mother. A sister is nua ɔbaa, a grandmother is nana and a paternal aunt is sewaa, so none of the other options matches. Therefore the correct answer is B: Mother.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_family_s2_003', 'topic_bece_ghlang_family', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'The Akan word “abusua” refers to what?', 'multiple_choice', NULL, '["A. The nuclear household only","B. A group of close friends","C. The extended family or clan","D. People of the same age group"]', 'C', 'Abusua is the extended family or clan — among the Akan it is the matrilineal family group traced through the mother. It goes far beyond the parents-and-children household, and it is defined by blood descent, not friendship or age. Therefore the correct answer is C: The extended family or clan.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_family_s2_004', 'topic_bece_ghlang_family', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'In Akan kinship, your “wɔfa” is which relative?', 'multiple_choice', NULL, '["A. Your father’s brother","B. Your sister’s husband","C. Your grandfather","D. Your mother’s brother (maternal uncle)"]', 'D', 'Wɔfa is the maternal uncle — the mother’s brother — who plays an important role in the matrilineal family. A father’s brother is regarded as another “father” (agya), and a sister’s husband and grandfather have different terms. Therefore the correct answer is D: Your mother’s brother (maternal uncle).', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, 'board_waec'),
('q_bghl_family_s2_005', 'topic_bece_ghlang_family', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, '“Sewaa” in Akan kinship refers to which relative?', 'multiple_choice', NULL, '["A. One’s father’s sister (paternal aunt)","B. One’s mother’s brother","C. One’s grandmother","D. One’s stepmother"]', 'A', 'Sewaa is the paternal aunt — the father’s sister. The mother’s brother is wɔfa, a grandmother is nana, and a stepmother is described differently, so only the father’s sister is correct. Therefore the correct answer is A: One’s father’s sister (paternal aunt).', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, 'board_waec'),
('q_bghl_family_s2_006', 'topic_bece_ghlang_family', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'The word “onua” refers to which family member?', 'multiple_choice', NULL, '["A. A cousin only","B. A sibling — a brother or a sister","C. A parent","D. A grandchild"]', 'B', 'Onua means a sibling. When the sex must be specified, Akan says nua barima (brother) or nua ɔbaa (sister). Parents are agya and ɛna, so onua cannot mean a parent or grandchild. Therefore the correct answer is B: A sibling — a brother or a sister.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_family_s2_007', 'topic_bece_ghlang_family', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'Among the Akan, a child traditionally inherits abusua (clan) membership from which side of the family?', 'multiple_choice', NULL, '["A. The father’s line","B. Both parents equally","C. The mother’s line","D. The chief’s lineage"]', 'C', 'The Akan practise matrilineal descent: abusua membership and inheritance pass through the mother, which is why the wɔfa (mother’s brother) is so important. Descent through the father’s line is patrilineal, the opposite system. Therefore the correct answer is C: The mother’s line.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_waec'),
('q_bghl_family_s2_008', 'topic_bece_ghlang_family', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'Kofi calls little Adjoa his “wɔfase”. What is their most likely relationship?', 'multiple_choice', NULL, '["A. Adjoa is Kofi’s own daughter","B. Kofi is Adjoa’s paternal uncle","C. Adjoa is Kofi’s cousin","D. Kofi is Adjoa’s maternal uncle — she is his sister’s child"]', 'D', 'Wɔfase is the nephew or niece of a wɔfa (maternal uncle) — that is, the sister’s child, who belongs to the same matrilineal abusua. A man’s own daughter belongs to her mother’s clan, not his, so she would not be his wɔfase. Therefore the correct answer is D: Kofi is Adjoa’s maternal uncle — she is his sister’s child.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Determine', 'AO3', NULL, NULL, 'board_waec');
INSERT INTO _migration_506_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_506_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_506_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'bece-ghlang-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_506_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'bece-ghlang-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/common-core-programme-ccp/', 0, 1 FROM _migration_506_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_506_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_506_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 8 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_506_expected e ON e.id = r.question_id WHERE r.batch_id IS 'bece-ghlang-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 8 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_506_expected e ON e.id = q.id) = 8 AND (SELECT COUNT(*) FROM questions q JOIN subjects s ON s.id = q.subject_id AND s.exam_type_id = q.exam_type_id JOIN _migration_506_expected e ON e.id = q.id) = 8 THEN 1 ELSE 0 END;
